ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'reports/duration_to_points_2026_10_16';OLD=ROOT/'reports/availability_probabilities_2026_10_16';TEMP=ROOT/'reports/availability_temporal_2026_10_16_attempt2';PRIOR=ROOT/'reports/minutes_to_points_2026_10_16_attempt2';CAL=ROOT/'reports/minute_calendar_2026_10_16';KEY=['season','round','code'];ID='duration-to-points-20261016-v1';ARMS={'matched':[],'duration':['forecast_minutes_given_play'],'any60':['forecast_any60_given_play'],'both':['forecast_minutes_given_play','forecast_any60_given_play']}
def folder(s,gw):return ROOT/('reports/fpl_simulator_2026_10_13/cache_manager' if s=='2025-26' else 'reports/fpl_improvement_2026_10_14/cache')/s/f'gw{gw:02d}'
def keyhash(q):return hashlib.sha256(q[KEY].to_csv(index=False).encode()).hexdigest()
def context():
 deps={};frames=[];audits=[]
 for s in ['2023-24','2024-25','2025-26']:
  source=TEMP if s=='2025-26' else OLD;path=source/('predictions.csv.gz' if s=='2025-26' else s+'_predictions.csv.gz');deps[str(path.relative_to(ROOT))]=sha(path);q=pd.read_csv(path)
  for gw,g in q.groupby('round',sort=True):
   stem=f'gw{gw:02d}' if s=='2025-26' else f'{s}_gw{gw:02d}';p=source/(stem+'.csv.gz');lock=read(source/(stem+'.lock.json'));assert sha(p)==lock['prediction_sha256'];pd.testing.assert_frame_equal(g.reset_index(drop=True),pd.read_csv(p));at=pd.Timestamp(lock['forecast_at']);fit=pd.Timestamp(lock['fit_cutoff']);assert fit<=at and (pd.to_datetime(g.forecast_at,utc=True)==at).all();assert lock['current_outcomes_joined'] is False
   refresh=1+4*((int(gw)-1)//4);fp=source/(f'fit{refresh:02d}.json' if s=='2025-26' else f'{s}_fit{refresh:02d}.json');fr=read(fp);assert pd.Timestamp(fr['fit_cutoff'])==fit
   for n in (['latest_label_at','latest_target_at'] if s=='2025-26' else ['max_label_available','max_train_origin']):assert pd.Timestamp(fr[n])<fit
   if s!='2025-26':
    mp=CAL/f'{s}_fit{refresh:02d}.json';mr=read(mp);assert pd.Timestamp(mr['max_label_available'])<fit;deps[str(mp.relative_to(ROOT))]=sha(mp)
   else:
    mp=TEMP/'frozen_mean_verification.json';assert pd.Timestamp(read(mp)['fit_cutoff'])<at;deps[str(mp.relative_to(ROOT))]=sha(mp)
   fdir=folder(s,int(gw));man=read(fdir/'manifest.json');assert pd.Timestamp(man['forecast_at'])==at
   for pp in [p,source/(stem+'.lock.json'),fp,fdir/'features.csv.gz',fdir/'pool.csv.gz',fdir/'manifest.json']:
    deps[str(pp.relative_to(ROOT))]=sha(pp)
   for n in ['features.csv.gz','pool.csv.gz']:assert sha(fdir/n)==man['files'][n]
   audits.append(dict(season=s,round=int(gw),forecast_at=str(at),minute_fit_cutoff=str(fit),rows=len(g),source=str(source.relative_to(ROOT))))
  keep=KEY+['forecast_at','can_buy','seen_this_season','position','fit_cutoff','candidate_p0','candidate_p1','candidate_p2','candidate_minutes','frozen_short_mean','frozen_long_mean'];frames.append(q[keep])
 q=pd.concat(frames,ignore_index=True);assert not q.duplicated(KEY).any();p=1-q.candidate_p0;assert np.allclose(q[['candidate_p0','candidate_p1','candidate_p2']].sum(axis=1),1);assert (q[['candidate_p0','candidate_p1','candidate_p2']]>=0).all().all();q['forecast_minutes_given_play']=np.divide(q.candidate_minutes,p,out=np.zeros(len(q)),where=p.to_numpy()>0)/90;q['forecast_any60_given_play']=np.divide(q.candidate_p2,p,out=np.zeros(len(q)),where=p.to_numpy()>0);assert np.isfinite(q[list(ARMS['both'])]).all().all();assert q.forecast_any60_given_play.between(0,1+1e-12).all();q.to_csv(OUT/'minute_inputs.csv.gz',index=False);atomic_json(OUT/'context.json',dict(dependencies=deps,origins=audits,labels_used_for_context=False,rows=len(q),excluded='2024/25 GW15 absent from both point-arm training sets because no qualified minute forecasts',feature_definition='E(round minutes|play)/90 and P(any fixture>=60|play); exact division by pplay, zero if pplay==0; no clipping of double-round duration'));print('CONTEXT',len(q),len(audits),flush=True)
def prepare():
 old=read(PRIOR/'proposal.json');files=dict(old['input_hashes']);files.update(read(OUT/'context.json')['dependencies'])
 for p in [Path(__file__),OUT/'context.json',OUT/'minute_inputs.csv.gz',PRIOR/'predictions.csv.gz',PRIOR/'predictions_complete.json',PRIOR/'complete.json',PRIOR/'verification.json',ROOT/'model_lab/minutes_to_points_v2.py']:
  files[str(p.relative_to(ROOT))]=sha(p)
 spec={**old,'id':ID,'candidate_id':'point_conditional_duration_any60_stack_v1','hypothesis':'Causal duration and any60 forecasts improve conditional point means beyond participation alone.','change':'Four fixed feature ablations on identical qualified forecast rows: matched history-only, duration-only, any60-only, both. Candidate is both only. Same CatBoost conditional point architecture, parameters, per-origin cadence and fixed availability participation. No minute refits.','related_work':['minutes-to-points-20261016-v2','availability-temporal-20261016-v2','availability-probabilities-20261016-v1'],'input_hashes':files,'features':'Original97 features from archived decision-time feature caches; add E(minutes|play)/90 and/or P(any fixture>=60|play) from causal saved minute forecasts. No realized minutes as input.','model_parameters':{'point_head':'same CatBoost200 depth5 rate.05 RMSE seed20261013, thread1','arms':ARMS,'mixture':'fixed pplay * conditional_mean + fixed p0 * matched training absent mean','negative_labels':'retained, no output clipping','training_scope':'Only rows with causal saved minute forecasts, from2023/24 onward; same exact keys in all four arms. Historical features taken from corresponding origin cache.'},'resources':{'threads':1,'maximum_head_fits':152,'origins':38,'arms':4,'minute_fits':0,'no_tuning':True},'evaluation_contract':{'target':'conditional expectation of harmonized round points, H1; MSE primary','season':'2025/26, previously inspected development period','primary_controls':['matched (same training rows and preprocessing)','retained previous candidate_points (more historical training, existing features)'],'candidate':'both prespecified; single-feature arms diagnostic only, no posthoc switching','training':'Saved per-row minute forecasts have fit cutoff<=historical origin and source label cutoff<fit. Point training forecast_at, target_h1_available_at and available_after_proxy strictly before current origin, finite target/minute and known fixture minutes. Preprocessing fit on all matched eligible rows, conditional head on played rows as existing method. All arms exact same rows, absence mean and fixed participation.','known_limitations':'Historical minute means refitted causally in2023/24 and2024/25;2025/26 fixed2024/25GW37 heads. Model family/features selected retrospectively; not prospective validation. Same Git timestamp and historical feature proxies. GW15 excluded from all matched point arms, retained prior head differs in history; require beating both controls.','gates':'both has strictly lower point MSE than EACH control in2025/26. Unchanged play/any60 probabilities must be identical and Brier no worse. No point10 probabilities invented.','pool':'Same38 origins and29,144 known eligible player-rounds as prior. can_buy and known points/minutes/all fixture-minute labels, identical masks.','uncertainty':'2000 paired four-calendar-round blocks seed20261015 per comparison, descriptive, multiple comparisons noted','secondary':'RMSE, MAE,bias; position,no_season_history; no outcome-based groups'},'success_criterion':'Prespecified both arm strictly beats matched AND retained point MSE in2025/26; identical play/any60 Brier. Diagnostic ablations cannot override failure.','stop_rule':'Stop on hash, source timing, key, invalid features or output mismatch. No automatic result-guided retries or tuning.','maximum_runs':1}
 atomic_json(OUT/'proposal.json',spec);print('PREPARED',len(files),flush=True)
def inputs():
 q=pd.read_csv(OUT/'minute_inputs.csv.gz');frames=[]
 for (s,gw),g in q.groupby(['season','round'],sort=False):
  f=pd.read_csv(folder(s,int(gw))/'features.csv.gz');assert not f.duplicated(KEY).any();assert (pd.to_datetime(f.forecast_at,utc=True)==pd.Timestamp(g.forecast_at.iloc[0])).all();v=g.merge(f.drop(columns='forecast_at'),on=KEY,how='left',sort=False,validate='one_to_one',indicator=True);assert v['_merge'].eq('both').all();frames.append(v.drop(columns='_merge'))
 q=pd.concat(frames,ignore_index=True);q.forecast_at=pd.to_datetime(q.forecast_at,utc=True);return q

def training(q,at):
 t=q[q.forecast_at.lt(at)&q.target_h1_available_at.lt(at)&q.available_after_proxy.lt(at)&q.target_total_points.notna()&q.native_minutes.notna()&q.minute_known.eq(True)].copy();assert len(t)>0;assert np.isfinite(t.target_total_points).all();return t

def labeled_inputs():
 q=inputs();rows,_,lab=load_data();timing=rows[KEY+['target_h1_available_at']];q=q.merge(lab,on=KEY,how='left',sort=False,validate='one_to_one').merge(timing,on=KEY,how='left',sort=False,validate='one_to_one');return q

def run():
 spec=read(OUT/'proposal.json');verify_files(ROOT,spec['input_hashes']);atomic_json(OUT/'started.json',dict(runtime=runtime(),proposal_sha256=sha(OUT/'proposal.json')));mod=adapter();a=mod.CausalCandidateForecaster(ROOT,thread_count=1);schema=a.schema;names=schema['extended_features'];data=labeled_inputs();retained=pd.read_csv(PRIOR/'predictions.csv.gz').set_index(KEY);frames=[]
 for gw in range(1,39):
  at=pd.Timestamp(read(folder('2025-26',gw)/'manifest.json')['forecast_at']);tr=training(data,at);played=tr.native_minutes.gt(0).to_numpy();assert played.any() and (~played).any();y=tr.target_total_points.to_numpy(float);absent=float(y[~played].mean());f=data[data.season.eq('2025-26')&data['round'].eq(gw)];q=f[KEY+['forecast_at','can_buy','seen_this_season','position','candidate_p0','candidate_p1','candidate_p2','candidate_minutes']+ARMS['both']].copy();q['retained_points']=retained.loc[pd.MultiIndex.from_frame(q[KEY]),'candidate_points'].to_numpy();assert np.array_equal(q.candidate_p0,retained.loc[pd.MultiIndex.from_frame(q[KEY]),'candidate_p0'].to_numpy());q['absent_points']=absent;q['point_fit_cutoff']=str(at);start=time.monotonic();arm_audits={}
  for arm,extra in ARMS.items():
   sc=copy.deepcopy(schema);sc['extended_features']=names+extra;X=tr[names+extra];pipe=a._pipeline.make_pipeline(sc,'catboost','extended',seed=mod.SEED,model_params={'thread_count':1});prep,reg=pipe.named_steps['prepare'],pipe.named_steps['model'];Z=prep.fit_transform(X)
   with threadpool_limits(limits=1):reg.fit(Z.loc[played],y[played],sample_weight=np.ones(int(played.sum())));conditional=reg.predict(prep.transform(f[names+extra]))
   q[arm+'_conditional']=conditional;q[arm+'_points']=(1-q.candidate_p0)*conditional+q.candidate_p0*absent;assert np.isfinite(q[arm+'_points']).all();arm_audits[arm]=dict(features=names+extra,training_keys_sha256=keyhash(tr),played_keys_sha256=keyhash(tr.loc[played]),training_rows=len(tr),played_rows=int(played.sum()))
  path=OUT/f'gw{gw:02d}.csv.gz';q.to_csv(path,index=False);atomic_json(OUT/f'gw{gw:02d}.lock.json',dict(prediction_sha256=sha(path),fit_cutoff=str(at),latest_training_origin=str(tr.forecast_at.max()),latest_point_label=str(tr.target_h1_available_at.max()),latest_minute_label=str(tr.available_after_proxy.max()),arms=arm_audits,current_outcomes_used_for_prediction=False));frames.append(q);print('ORIGIN',gw,'rows',len(tr),'seconds',round(time.monotonic()-start,1),flush=True)
 pd.concat(frames,ignore_index=True).to_csv(OUT/'predictions.csv.gz',index=False);verify_files(ROOT,spec['input_hashes']);atomic_json(OUT/'predictions_complete.json',dict(prediction_sha256=sha(OUT/'predictions.csv.gz'),head_fits=152,minute_fits=0));print('PREDICTIONS COMPLETE',flush=True)
def score():
 spec=read(OUT/'proposal.json');verify_files(ROOT,spec['input_hashes']);assert sha(OUT/'predictions.csv.gz')==read(OUT/'predictions_complete.json')['prediction_sha256'];_,_,lab=load_data();q=pd.read_csv(OUT/'predictions.csv.gz');z=q.merge(lab,on=KEY,how='left',validate='one_to_one');mask=z.can_buy&z.native_minutes.notna()&z.target_total_points.notna()&z.minute_known.eq(True);coverage=dict(requested=int(z.can_buy.sum()),known=int(mask.sum()),unknown=int((z.can_buy&~mask).sum()));z=z[mask].copy();prior=pd.read_csv(PRIOR/'scores.csv.gz');assert set(map(tuple,z[KEY].to_numpy()))==set(map(tuple,prior[KEY].to_numpy()));stats=[];arms=['retained']+list(ARMS)
 for arm in arms:z[arm+'_error']=z[arm+'_points']-z.target_total_points;z[arm+'_mse']=z[arm+'_error']**2
 z['play_brier']=(1-z.candidate_p0-z.native_minutes.gt(0).astype(float))**2;z['any60_brier']=(z.candidate_p2-z.any60.astype(float))**2
 for k in ['play_brier','any60_brier']:assert np.allclose(z.set_index(KEY)[k].sort_index(),prior.set_index(KEY)['candidate_'+k].sort_index(),atol=1e-12,rtol=1e-12)
 cohorts={'all':z,'no_season_history':z[~z.seen_this_season]};cohorts.update({f'position_{p}':z[z.position.eq(p)] for p in sorted(z.position.unique())})
 for cohort,g in cohorts.items():
  for arm in arms:
   e=g[arm+'_error'];stats.append(dict(cohort=cohort,arm=arm,n=len(g),mse=float((e**2).mean()),rmse=float(np.sqrt((e**2).mean())),mae=float(e.abs().mean()),bias=float(e.mean())))
 m=pd.DataFrame(stats);m.to_csv(OUT/'metrics.csv',index=False);z.to_csv(OUT/'scores.csv.gz',index=False);primary=m[m.cohort.eq('all')].set_index('arm');gates={f'mse_vs_{arm}':bool(primary.loc['both','mse']<primary.loc[arm,'mse']) for arm in ['matched','retained']};gates['probabilities_identical']=True;rng=np.random.default_rng(20261015);pairs=[('both','matched'),('both','retained'),('duration','matched'),('any60','matched'),('both','duration'),('both','any60')];ds=[z.assign(delta=z[a+'_mse']-z[b+'_mse']).groupby('round').delta.agg(['sum','count']).reindex(range(1,39)).to_numpy() for a,b in pairs];draw=[]
 for _ in range(2000):
  ix=np.concatenate([np.arange(i,i+4) for i in rng.integers(0,35,10)])[:38];draw.append([d[ix,0].sum()/d[ix,1].sum() for d in ds])
 draw=np.array(draw);intervals=[dict(candidate=a,control=b,difference=float((z[a+'_mse']-z[b+'_mse']).mean()),lower=float(np.quantile(draw[:,i],.025)),upper=float(np.quantile(draw[:,i],.975))) for i,(a,b) in enumerate(pairs)];pd.DataFrame(intervals).to_csv(OUT/'intervals.csv',index=False);atomic_json(OUT/'complete.json',dict(research_gate_passed=all(gates.values()),gates=gates,coverage=coverage,primary_results=primary.reset_index().to_dict('records'),intervals=intervals,minute_predictions_unchanged=True,manager_promoted=False));print('GATES',gates,flush=True);print(primary.to_string(),flush=True)
if __name__=='__main__':globals()[sys.argv[1]]()
